paragraph.math:
$$\begin{array}{lll}
  {s(x)} & = & {(f + g)(x) = f(x) + g(x) = \sqrt{x + 1} + 2x + 1} \\
  {d(x)} & = & {(f - g)(x) = f(x) - g(x) = \sqrt{x + 1} - (2x + 1) = \sqrt{x + 1} - 2x - 1} \\
  {p(x)} & = & {\left( \mathit{fg} \right)(x) = f(x)g(x) = \sqrt{x + 1}(2x + 1) = (2x + 1)\sqrt{x + 1}}
  \end{array}$$

$$\begin{array}{l}
  {(f \circ g){(x) = f(g(x)) = \left( g(x) \right)^{2} - 1 = \left( \sqrt{x} + 1 \right)^{2} - 1}} \\
  {\phantom{(f \circ g)(x)} = x + 2\sqrt{x} + 1 - 1 = x + 2\sqrt{x}}
  \end{array}$$

$$\begin{array}{lll}
  {s(x)} & = & {f(x) + g(x) = \sqrt{x} + 1 + \frac{x}{1 + x}} \\
  {d(x)} & = & {f(x) - g(x) = \sqrt{x} + 1 - \frac{x}{1 + x}} \\
  {p(x)} & = & {f(x)g(x) = (\sqrt{x} + 1) \cdot \frac{x}{1 + x} = \frac{x(\sqrt{x} + 1)}{1 + x}} \\
  {q(x)} & = & {\frac{f(x)}{g(x)} = \frac{\sqrt{x} + 1}{\frac{x}{1 + x}} = \frac{(\sqrt{x} + 1)(1 + x)}{x}}
  \end{array}$$
